from datetime import datetime

# Use existing gmail_token from earlier
assert 'gmail_token' in globals() and gmail_token

all_sched_drafts=[]
page_index=0
page_limit=20
while True:
    r = apis.gmail.show_drafts(access_token=gmail_token, scheduled=True, page_index=page_index, page_limit=page_limit)
    if not isinstance(r, list):
        # if API returns dict with list
        drafts = r.get('drafts', r.get('results', []))
    else:
        drafts = r
    print('page_index', page_index, 'returned', len(drafts))
    if not drafts:
        break
    all_sched_drafts.extend(drafts)
    page_index += 1
    if page_index>50:
        break

print('total_scheduled_drafts', len(all_sched_drafts))
# print sample subjects/dates
for d in all_sched_drafts[:15]:
    print('draft_id', d.get('draft_id'), 'subject', d.get('subject'), 'scheduled_send_at', d.get('scheduled_send_at'), 'created_at', d.get('created_at'))

# show time range
sched_times=[]
for d in all_sched_drafts:
    t=d.get('scheduled_send_at')
    if t:
        try:
            sched_times.append(datetime.fromisoformat(t.replace('Z','+00:00')))
        except Exception:
            pass
if sched_times:
    print('scheduled_send_at_min', min(sched_times).isoformat())
    print('scheduled_send_at_max', max(sched_times).isoformat())

created_times=[]
for d in all_sched_drafts:
    t=d.get('created_at')
    if t:
        try:
            created_times.append(datetime.fromisoformat(t.replace('Z','+00:00')))
        except Exception:
            pass
if created_times:
    print('created_at_min', min(created_times).isoformat())
    print('created_at_max', max(created_times).isoformat())

